// Задача человеку «разобраться» на польском: её читают сотрудники Заказчика. Ссылка на Беседу —
// родитель задачи в CRM, Заказ-наряд — по его id.
const CHANNELS = { messenger: 'Messenger', instagram: 'Instagram', whatsapp: 'WhatsApp', call: 'Telefon' };
const rated = $json;
const client = rated.name || `${CHANNELS[rated.channel]} · ${rated.sender_id}`;
const description = [
  `Ocena naprawy: ${rated.rating}/5`,
  `Kanał: ${CHANNELS[rated.channel]}`,
  ...(rated.phone ? [`Telefon: ${rated.phone}`] : []),
  `Zlecenie naprawy: ${rated.crm_repair_order_id}`,
  'Skontaktuj się z klientem i wyjaśnij, co poszło nie tak.',
].join('\n');
return { json: { name: `Zła ocena naprawy ${rated.rating}/5: ${client}`, description } };
